<script setup lang="ts">
import DecorationColorField from './DecorationColorField.vue'
import {clientPageBackground,decorationTheme} from '../../../../api/src/core/decoration-contract.mjs'
import type {DecorationTheme} from '../../../../api/src/core/decoration-types'
defineProps<{disabled?:boolean}>()
defineEmits<{inheritAll:[]}>()
const value=defineModel<DecorationTheme>({required:true})
const presets=[{name:'清爽蓝',primary:'#2563eb',radius:12},{name:'自然绿',primary:'#059669',radius:12},{name:'温暖橙',primary:'#ea580c',radius:16},{name:'简约黑',primary:'#18181b',radius:4}]
function apply(p:typeof presets[number]){value.value={...decorationTheme(),primary:p.primary,radius:p.radius}}
</script>
<template><div class="theme-panel"><section><h3>风格预设</h3><div class="theme-presets"><button v-for="p in presets" :key="p.name" type="button" :disabled="disabled" :class="{active:value.primary===p.primary}" @click="apply(p)"><span class="theme-swatch" :style="{background:clientPageBackground}"><i :style="{background:p.primary}"/><i :style="{background:p.primary,opacity:.35}"/></span><span>{{p.name}}</span></button></div></section><section><h3>主题颜色</h3><div class="theme-colors"><DecorationColorField v-model="value.primary" label="品牌主色" :disabled="disabled"/><DecorationColorField :model-value="clientPageBackground" label="页面背景" disabled/><DecorationColorField v-model="value.surface" label="组件背景" :disabled="disabled"/><DecorationColorField v-model="value.text" label="主要文字" :disabled="disabled"/><DecorationColorField v-model="value.muted" label="辅助文字" :disabled="disabled"/></div></section><section><h3>排版与布局</h3><label v-for="field in [{key:'fontSize',name:'基础字号',min:12,max:22},{key:'radius',name:'组件圆角',min:0,max:40},{key:'spacing',name:'组件间距',min:0,max:32}] as const" :key="field.key" class="theme-slider"><span>{{field.name}}<b>{{value[field.key]}} px</b></span><input v-model.number="value[field.key]" type="range" :min="field.min" :max="field.max" :disabled="disabled"></label></section><UButton color="neutral" variant="outline" icon="i-lucide-paintbrush" :disabled="disabled" @click="$emit('inheritAll')">整套方案统一跟随主题</UButton><p class="text-xs text-muted leading-6">主题颜色应用于组件与导航，页面底色遵循统一标准。已有自定义样式保持不变。</p></div></template>
<style scoped>.theme-panel{display:grid;gap:24px}.theme-panel h3{font-size:13px;font-weight:600;margin-bottom:14px}.theme-presets{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.theme-presets>button{border:1px solid var(--ui-border);border-radius:8px;padding:8px;text-align:left;font-size:11px;cursor:pointer}.theme-presets>button.active{border-color:var(--ui-primary);color:var(--ui-primary)}.theme-swatch{height:44px;border-radius:4px;display:flex;align-items:center;gap:5px;padding:10px;margin-bottom:7px}.theme-swatch i{display:block;width:26px;height:24px;border-radius:4px}.theme-colors{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.theme-slider{display:grid;gap:12px;margin-bottom:18px}.theme-slider>span{display:flex;align-items:center;justify-content:space-between;font-size:12px;color:var(--ui-text-muted)}.theme-slider b{font:11px ui-monospace,monospace;color:var(--ui-text)}.theme-slider input{width:100%;accent-color:var(--ui-primary)}</style>
